pay=pagehero('Hayalows payments','Pay an agreed invoice.','Use this page after confirming the project and amount with Hayalows. Card and Mobile Money payments are handled by Paystack.')+'<section class="container studio-section compact payment-studio-grid"><div>'+route+'<div class="studio-ussd"><p class="label">Or use USSD</p>'+ussd+'</div></div><aside class="payment-next"><p class="label">What happens next</p><ol><li>Keep your Paystack receipt and transaction reference.</li><li>Share the reference with Hayalows if confirmation is needed.</li><li>We confirm the next project step based on your agreed scope.</li></ol><p>Your PIN stays private. Never send card details or your Mobile Money PIN in a message.</p><a class="studio-link" href="/payments-and-refunds/">Payments &amp; refunds policy ↗</a><p class="small">Looking for detergent products? <a href="/fiftys-bliss/">50&apos;s Bliss has its own page ↗</a></p></aside></section>'+dialog+'<script src="/payment.js?v=20261020" defer></script>'
write('/pay/','Pay an Agreed Invoice | Hayalows','Pay an agreed Hayalows invoice through Paystack or the published USSD code. Keep your payment reference and contact Hayalows for help.',pay)
# Give the existing policy pages the same navigation, footer and Inter system.
for slug in ['privacy','terms','payments-and-refunds']:
    path=ROOT/slug/'index.html';text=path.read_text(encoding='utf-8-sig')
    text=re.sub(r'<header class="site-header">[\s\S]*?</header>',nav,text)
    text=re.sub(r'<footer class="site-footer">[\s\S]*?</footer>',footer,text)
    text=re.sub(r'<link rel="stylesheet" href="/studio.css[^>]*>', '', text)
    text=text.replace('</head>','<link rel="stylesheet" href="/studio.css?v=20261020-3"></head>')
    text=text.replace('<body>','<body class="studio">');path.write_text(text)
paths=['/','/work/','/about/','/prices/','/contact/','/pay/','/fiftys-bliss/','/privacy/','/terms/','/payments-and-refunds/']+['/work/'+p['slug']+'/' for p in projects]
(ROOT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>https://hayalows.com'+p+'</loc></url>' for p in paths)+'</urlset>')
(ROOT/'_redirects').write_text('/services /#what-we-do 301\n/products /fiftys-bliss/ 302\n')
